/**
 * Private file storage for avatars and request attachments.
 *
 * Bytes are written OUTSIDE the SvelteKit webroot/static dir, under
 * `<project root>/storage/`, so nothing here is ever reachable by a plain
 * static URL — every read goes through an authenticated, ownership-checked
 * `+server.ts` route (see `src/routes/app/avatar/+server.ts` and
 * `src/routes/app/attachments/[kind]/[id]/+server.ts`).
 *
 * Keys are always generated by this server (a `randomBytes` hex string, or
 * an employee's own cuid `id`) — never taken verbatim from user input — but
 * `resolveSafe` still defends in depth against path traversal.
 */
import { mkdir, writeFile, readFile, unlink } from 'node:fs/promises';
import { randomBytes } from 'node:crypto';
import path from 'node:path';

const STORAGE_ROOT = path.resolve(process.cwd(), 'storage');

export const ALLOWED_AVATAR_MIME_TYPES = ['image/jpeg', 'image/png', 'image/webp'] as const;
export const MAX_AVATAR_SIZE_BYTES = 2 * 1024 * 1024; // 2 MB

export const ALLOWED_ATTACHMENT_MIME_TYPES = [
	'application/pdf',
	'image/jpeg',
	'image/png',
	'image/webp'
] as const;
export const MAX_ATTACHMENT_SIZE_BYTES = 10 * 1024 * 1024; // 10 MB

function resolveSafe(...segments: string[]): string {
	const target = path.resolve(STORAGE_ROOT, ...segments);
	if (target !== STORAGE_ROOT && !target.startsWith(STORAGE_ROOT + path.sep)) {
		throw new Error('Refused to resolve a storage path outside the storage root.');
	}
	return target;
}

export function generateStorageKey(): string {
	return randomBytes(16).toString('hex');
}

async function writeToStorage(subdir: string, key: string, file: File): Promise<void> {
	const dir = resolveSafe(subdir);
	await mkdir(dir, { recursive: true });
	const buffer = Buffer.from(await file.arrayBuffer());
	await writeFile(resolveSafe(subdir, key), buffer);
}

async function readFromStorage(subdir: string, key: string): Promise<Buffer | null> {
	try {
		return await readFile(resolveSafe(subdir, key));
	} catch {
		return null;
	}
}

async function deleteFromStorage(subdir: string, key: string): Promise<void> {
	try {
		await unlink(resolveSafe(subdir, key));
	} catch {
		// Already gone — fine.
	}
}

/** Avatar files are keyed by the employee's own id (one avatar per employee). */
export const saveAvatar = (employeeId: string, file: File) =>
	writeToStorage('avatars', employeeId, file);
export const readAvatar = (employeeId: string) => readFromStorage('avatars', employeeId);
export const deleteAvatar = (employeeId: string) => deleteFromStorage('avatars', employeeId);

export type AttachmentKind = 'benefit' | 'leave';

export const saveAttachment = (kind: AttachmentKind, key: string, file: File) =>
	writeToStorage(`${kind}-attachments`, key, file);
export const readAttachment = (kind: AttachmentKind, key: string) =>
	readFromStorage(`${kind}-attachments`, key);
